65	          <td>{{ a.created_at }}</td>
66	          <td>{% if a.line_bound %}<span class="line-yes">✓ 已綁定</span>{% else %}<span class="line-no">未綁定</span>{% endif %}</td>
67	        </tr>
68	        {% endfor %}
69	      </table>
70	      {% if not attendees %}<div class="empty">目前還沒有來賓資料</div>{% endif %}
71	    </div>
72	  </div>
