1943	const cards = document.querySelectorAll('.case-card');
1944	const obs = new IntersectionObserver(entries => {
1945	  entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('revealed'); obs.unobserve(e.target); } });
1946	}, { threshold: 0.1 });
1947	cards.forEach(c => obs.observe(c));
1948	function animateCount(e){var t=parseInt(e.dataset.target),n=0,s=Math.max(Math.ceil(t/60),1),i=setInterval(function(){n=Math.min(n+s,t),e.textContent=n.toLocaleString(),n>=t&&clearInterval(i)},16)}var so=new IntersectionObserver(function(e){e.forEach(function(e){e.isIntersecting&&(animateCount(e.target),so.unobserve(e.target))})},{threshold:.5});document.querySelectorAll(".counting").forEach(function(e){so.observe(e)});
